      "Os testes mais comuns avaliam capacidades físicas distintas: corrida (avalia capacidade aeróbica/cardiorrespiratória, geralmente 12 minutos ou distância fixa como 2.400m ou 3.000m), flexão de braço e abdominal (avaliam resistência muscular localizada, contando repetições em tempo determinado), barra fixa (avalia força de membros superiores), e, em algumas corporações, teste de natação e de agilidade (shuttle run).",
      "Cada teste tem uma lógica fisiológica diferente por trás, o que significa que o treino precisa ser específico: treinar só corrida não prepara adequadamente para o teste de barra, e vice-versa — a preparação eficiente para o TAF combina, ao longo de semanas, os diferentes tipos de estímulo (aeróbico, força, resistência muscular), não apenas repetição do próprio teste isoladamente."
