    "corpo": [
      "Antes de buscar treinos intensos, é fundamental construir uma base aeróbica sólida: correr em ritmo confortável (onde ainda seria possível manter uma conversa, o chamado 'ritmo de conversa') por períodos crescentes, algumas vezes por semana, antes de progredir para treinos mais intensos — pular essa etapa é uma das causas mais comuns de lesão em quem está começando a treinar para o TAF.",
      "Depois de construída essa base (normalmente algumas semanas de corrida regular e confortável), o treino intervalado passa a ser útil: alternar períodos de corrida mais intensa com períodos de recuperação em ritmo mais leve (ex.: 1 minuto forte, 2 minutos leve, repetindo algumas vezes) — esse tipo de estímulo melhora a capacidade de sustentar ritmo mais forte por mais tempo, que é exatamente o que o teste de corrida do TAF exige.",
      "A progressão deve ser gradual: aumentar o volume total de corrida em pequenos incrementos (evitando saltos bruscos de uma semana para outra), respeitando dias de descanso entre sessões mais puxadas, e prestando atenção a sinais de desconforto (dor persistente, não apenas cansaço muscular normal) que podem indicar necessidade de reduzir a carga ou buscar avaliação profissional."
    ],
    "pontosChave": [
      "Construa base aeróbica primeiro (ritmo confortável, de conversa) antes de buscar treinos intensos.",
      "Treino intervalado (alternar intensidade e recuperação) é útil depois de estabelecida a base, para melhorar ritmo sustentado.",
      "Progrida gradualmente, com dias de descanso, e preste atenção a sinais de dor persistente (diferente de cansaço normal)."
    ],
