    "corpo": [
      "O teste de abdominal do TAF avalia resistência muscular localizada — a capacidade de realizar muitas repetições de um movimento específico dentro de um tempo determinado (geralmente 1 minuto). Diferente de força máxima (levantar o máximo de peso possível uma vez), resistência muscular exige treino com repetições mais altas e menor carga, focando em manter a qualidade do movimento ao longo de todas as repetições, não apenas nas primeiras.",
      "'Core' é o conjunto de músculos do tronco (abdômen, lombar, quadril) que estabilizam o corpo durante qualquer movimento — treinar apenas o abdômen isoladamente, sem fortalecer a musculatura lombar e de estabilização, pode gerar desequilíbrio muscular. Exercícios como prancha (isometria, sustentar a posição por tempo determinado, sem movimento) complementam bem o abdominal tradicional dinâmico, fortalecendo o core de forma mais completa.",
      "A técnica correta de execução do abdominal cobrado no TAF costuma seguir um padrão específico definido pelo edital (posição das mãos, ângulo do movimento, o que conta ou não como repetição válida) — treinar exatamente no padrão de contagem oficial da banca examinadora evita que o candidato treine uma variação diferente da exigida e seja surpreendido no dia da prova com um padrão de contagem mais rigoroso do que o praticado."
    ],
    "pontosChave": [
      "Abdominal do TAF avalia resistência muscular (muitas repetições), diferente de força máxima (uma repetição pesada).",
      "Core inclui abdômen, lombar e quadril — treinar só o abdômen isoladamente pode gerar desequilíbrio muscular.",
      "Treine no padrão exato de execução e contagem do edital/banca, não em uma variação genérica diferente."
    ],
    "checkRapido": {
      "pergunta": "O teste de abdominal do TAF avalia principalmente qual capacidade física?",
      "opcoes": [
        "Força máxima",
        "Resistência muscular localizada",
        "Flexibilidade"
      ],
      "correta": 1,
      "justificativa": "Ao exigir muitas repetições em tempo determinado, o teste avalia a capacidade de sustentar contrações musculares repetidas ao longo do tempo (resistência muscular localizada), não a capacidade de gerar força máxima em um único movimento."
    },
    "oQueCobra": "Reconhecer a diferença entre resistência muscular e força máxima, e a importância de treinar core de forma equilibrada.",
    "precisaSaberAntes": "Nenhum pré-requisito técnico específico.",
    "explicacao": [
      {
        "titulo": "Progressão segura de volume no treino de abdominal",
        "texto": "Assim como na corrida, o volume de repetições deve progredir gradualmente ao longo das semanas de treino, permitindo adaptação da musculatura e evitando sobrecarga excessiva e repentina — treinar até a exaustão completa todos os dias, sem variação, tende a ser menos eficiente do que uma progressão estruturada com dias de menor intensidade intercalados."
      },
      {
        "titulo": "Confirme o padrão de contagem antes de treinar por meses no padrão errado",
        "texto": "Editais e bancas examinadoras podem exigir padrões específicos (cotovelo tocando o joelho, mãos atrás da cabeça sem puxar o pescoço, entre outras variações) — buscar essa informação específica antes de estruturar o treino evita meses de prática em um padrão que não será exatamente o exigido na avaliação real."
      }
    ],
