    "explicacaoComoSeTivesse12": "Imagine como evoluir em um jogo de fases: técnica, constância e descanso valem mais do que tentar fazer tudo de uma vez. Neste capítulo, \"Fortalecimento de core e abdominal\", a ideia principal é: O teste de abdominal do TAF avalia resistência muscular localizada — a capacidade de realizar muitas repetições de um movimento específico dentro de um tempo determinado (geralmente 1 minuto). Para estudar sem travar, guarde primeiro estas palavras-chave: core, técnica de execução, resistência muscular localizada. Depois responda: o que a banca quer que eu reconheça? A frase de memória é: Treine no padrão exato do edital, com progressão gradual — core inclui lombar e quadril, não só o abdômen isoladamente.",
