    "title": "Barra fixa: técnica e progressão",
    "assunto": "Treino de força de membros superiores",
    "tecnica": "Uso de exercícios auxiliares antes da barra completa",
    "competencia": "Estruturar uma progressão segura para desenvolver força suficiente para a barra fixa completa",
    "dificuldade": "Difícil",
    "tempoLeituraMin": 7,
    "tempoExercicioMin": 5,
    "bancaRatings": {
      "FGV": 1,
      "CESPE": 1,
      "FCC": 1,
      "ENEM": 1
    },
    "termosChave": [
      "barra fixa",
      "exercício auxiliar",
      "força relativa"
    ],
    "corpo": [
      "Barra fixa é considerada um dos testes mais desafiadores do TAF para grande parte dos candidatos, especialmente mulheres (por diferenças fisiológicas médias de proporção força/peso corporal entre os sexos, refletidas em índices mínimos geralmente diferenciados por sexo no edital). O movimento trabalha principalmente dorsais, bíceps e músculos do ombro, exigindo força relativa considerável (força em relação ao próprio peso corporal).",
      "Para quem ainda não consegue nenhuma repetição completa, exercícios auxiliares são fundamentais antes de simplesmente tentar repetidamente a barra completa sem sucesso: negativas (subir com ajuda, como um banco ou impulso das pernas, e descer lentamente de forma controlada, focando na fase excêntrica do movimento), remada com elástico ou em máquina (fortalece os mesmos grupos musculares com carga ajustável), e dead hang (simplesmente sustentar o corpo pendurado na barra, fortalecendo a pegada e preparando ombros/cotovelos para o movimento completo).",
      "A progressão de força para barra fixa costuma ser mais lenta do que para outros testes do TAF, exigindo paciência e constância — negativas controladas e trabalho de remada, praticados de forma consistente por várias semanas, tendem a gerar progresso mais sólido e sustentável do que tentativas repetidas e frustradas da barra completa sem essa base de força auxiliar construída previamente."
    ],
