    "explicacaoComoSeTivesse12": "Imagine como evoluir em um jogo de fases: técnica, constância e descanso valem mais do que tentar fazer tudo de uma vez. Neste capítulo, \"Aquecimento e prevenção de lesões\", a ideia principal é: Um aquecimento bem estruturado segue uma progressão do geral para o específico: primeiro alguns minutos de atividade cardiovascular leve (caminhada rápida, trote leve, polichinelo) para elevar gradualmente a temperatura corporal e a frequência cardíaca, depois. Para estudar sem travar, guarde primeiro estas palavras-chave: aquecimento específico, sobrecarga progressiva, overtraining. Depois responda: o que a banca quer que eu reconheça? A frase de memória é: Reduza o volume na última semana antes da prova (não aumente); dor persistente pede avaliação, não insistência no mesmo treino.",
