      "Nutrição adequada oferece suporte importante ao desempenho físico e à recuperação entre os treinos, mas este capítulo traz apenas princípios gerais — planos alimentares individualizados, com metas específicas de calorias ou macronutrientes, devem ser orientados por nutricionista, considerando o histórico de saúde, objetivos e necessidades específicas de cada pessoa, e não por uma apostila genérica.",
      "Alguns princípios gerais amplamente reconhecidos: manter uma alimentação variada, com boa presença de vegetais, frutas, proteínas e carboidratos que forneçam energia para o treino; hidratar-se adequadamente ao longo do dia, e especialmente antes, durante e depois de sessões de treino mais intensas ou em dias muito quentes; e dar atenção à recuperação após o treino, com uma refeição equilibrada dentro de algumas horas, para apoiar a recuperação muscular.",
      "É importante evitar abordagens extremas ou restritivas sem orientação profissional — dietas muito restritivas, jejuns prolongados combinados com treino intenso, ou preocupação excessiva com números específicos de calorias podem prejudicar tanto o desempenho físico quanto o bem-estar geral. Se a preparação para o TAF estiver gerando ansiedade excessiva em relação à alimentação ou ao peso corporal, vale conversar com um profissional de saúde, já que isso vai muito além do que qualquer material de estudo pode orientar com segurança."
