    "explicacaoComoSeTivesse12": "Imagine como evoluir em um jogo de fases: técnica, constância e descanso valem mais do que tentar fazer tudo de uma vez. Neste capítulo, \"Nutrição básica para desempenho físico\", a ideia principal é: Nutrição adequada oferece suporte importante ao desempenho físico e à recuperação entre os treinos, mas este capítulo traz apenas princípios gerais — planos alimentares individualizados, com metas específicas de calorias ou macronutrientes, devem ser. Para estudar sem travar, guarde primeiro estas palavras-chave: hidratação, alimentação equilibrada, janela de recuperação. Depois responda: o que a banca quer que eu reconheça? A frase de memória é: Princípios gerais aqui, plano específico com nutricionista — evite restrição extrema, e não experimente alimento novo perto da prova.",
