    "explicacaoComoSeTivesse12": "Imagine como evoluir em um jogo de fases: técnica, constância e descanso valem mais do que tentar fazer tudo de uma vez. Neste capítulo, \"Recuperação e descanso\", a ideia principal é: O ganho de capacidade física (força, resistência) acontece principalmente durante o período de recuperação após o estímulo do treino, não durante o treino em si — o corpo se adapta e se fortalece no descanso, então negligenciar essa etapa (treinando. Para estudar sem travar, guarde primeiro estas palavras-chave: sono e recuperação, descanso ativo, periodização. Depois responda: o que a banca quer que eu reconheça? A frase de memória é: O corpo fortalece durante o descanso, não durante o treino — sono de qualidade e dias de menor intensidade são parte do processo, não ausência dele.",
