      "Uma estrutura semanal equilibrada, adaptável ao nível individual de condicionamento, tende a alternar: dias focados em capacidade aeróbica (corrida), dias focados em força/resistência muscular (flexão, abdominal, barra, com algum intervalo de recuperação entre esses estímulos), e ao menos um dia de descanso mais completo ou atividade bem leve — nunca treinando todos os componentes no máximo esforço todos os dias da semana.",
