    "explicacaoComoSeTivesse12": "Imagine como evoluir em um jogo de fases: técnica, constância e descanso valem mais do que tentar fazer tudo de uma vez. Neste capítulo, \"Simulado de TAF: montando sua semana de treino\", a ideia principal é: Depois de entender cada componente separadamente (corrida, abdominal, flexão, barra, mobilidade, recuperação), o passo final é organizá-los em uma semana equilibrada, sem sobrecarregar os mesmos grupos musculares em dias seguidos, e sem negligenciar nenhum dos testes exigidos pelo edital específico do concurso almejado. Para estudar sem travar, guarde primeiro estas palavras-chave: planejamento semanal, simulado completo, distribuição de estímulos. Depois responda: o que a banca quer que eu reconheça? A frase de memória é: Distribua os estímulos ao longo da semana, inclua descanso, e simule as condições reais periodicamente — nunca treine tudo no máximo todo dia.",
